// Necessary supply of distinct common supports, given the six matched exclusive rows.
#[allow(dead_code)]mod engine{include!("ramsey310_bulk_side.rs");pub fn run(){let args:Vec<_>=env::args().collect();let txt=fs::read_to_string(&args[1]).unwrap();let mut it=txt.split_whitespace().map(|s|s.parse::<u32>().unwrap());let mut read=||{let n=it.next().unwrap();(0..n).map(|_|it.next().unwrap()).collect::<Vec<_>>()};let a=read();let _=read();let six=read();let seven=read();assert!(seven.len()<=768);let mut inc=[B::default();26];let mut full=B::default();for (i,&s) in seven.iter().enumerate(){full.put(i);for v in 0..26{if s>>v&1!=0{inc[v].put(i)}}}let ts:Vec<_>=seven.iter().chain(&six).map(|&t|{let mut hit=B::default();for v in 0..26{if t>>v&1!=0{hit.add(inc[v])}}(t,t.count_ones()as i32,hit)}).collect();let table=fs::read_to_string(&args[2]).unwrap();let mut tested=0;let mut passed=0;for line in table.lines(){let e:Vec<_>=line.split_whitespace().map(|s|s.parse::<u32>().unwrap()).collect();let mut p=full;let mut need=[0;26];let mut ones=0;for v in 0..26{need[v]=9-a[v].count_ones()-e.iter().map(|s|s>>v&1).sum::<u32>();if need[v]==1{ones|=1<<v}}for m in 0..8{let u=e[3*(m&1)]|e[1+3*((m>>1)&1)]|e[2+3*((m>>2)&1)];let mut z=ones&!u;while z!=0{let i=z.trailing_zeros()as usize;z&=z-1;let mut zz=z;while zz!=0{let j=zz.trailing_zeros()as usize;zz&=zz-1;p.sub(inc[i].and(inc[j]))}}}for &(t,k,hit) in &ts{let b=(0..3).filter(|&j|t&e[j]!=0&&t&e[3+j]!=0).count()as i32;if 6-k+b==0{p=p.and(hit)}}tested+=1;if p.count()>=6&&(0..26).all(|v|p.and(inc[v]).count()>=need[v]){passed+=1;println!("{line}")}}eprintln!("supply tested {tested} passed {passed}")}}
fn main(){engine::run()}
